import fs from 'fs/promises';
import path from 'path';
import { z } from 'zod';
import {
  GuidanceDocumentSchema,
  GuidanceUploadSchema,
  GuidanceUploadUpdateSchema,
} from '../../types/guidance';
import { GUIDANCE_FLAG_SPEC, guidanceSelectionFromFlags } from '../guidance';
import { booleanFlag, stringFlag } from '../flags';
import { errorResult, type CliCommandResult } from '../envelope';
import { parseCommandContext, isCommandResult } from './shared';
import { guidanceUpload } from './guidanceUpload';
import { errorMessage } from '../../utils/errorMessage';
import { guidanceReferences, readGuidanceText } from './guidanceReferences';
import { guidanceVerifierPackage } from './guidanceVerifierPackage';
import { contextSourceRequest } from './contextSourceRequest';
import { sourceRefreshScope } from '../sourceRefresh';

interface ContextRequest {
  command: string;
  endpoint: string;
  method: string;
  body: unknown;
  projectPath: string;
  isProjectRequest: boolean;
  verificationTarget?: Record<string, unknown>;
  outputDirectory?: string;
}

const ACTION_FLAGS = {
  add: {
    title: { takesValue: true },
    file: { takesValue: true },
    references: { takesValue: true },
    source: { takesValue: true },
  },
  update: {
    title: { takesValue: true },
    file: { takesValue: true },
    references: { takesValue: true },
    verifier: { takesValue: true },
    'verifier-package': { takesValue: true },
    'source-digest': { takesValue: true },
    'remove-verifier': { takesValue: false },
    source: { takesValue: true },
    'remove-source': { takesValue: false },
  },
  verifier: {},
  verify: {
    input: { takesValue: true },
    'output-directory': { takesValue: true },
  },
  list: {},
  show: {},
  enable: {},
  disable: {},
  remove: {},
  inspect: {},
  refresh: {
    all: { takesValue: false },
    preview: { takesValue: false },
  },
  resolve: GUIDANCE_FLAG_SPEC,
};
const ActionSchema = z.enum([
  'add',
  'update',
  'list',
  'show',
  'enable',
  'disable',
  'remove',
  'resolve',
  'inspect',
  'verifier',
  'verify',
  'refresh',
]);

const readMarkdown = async (file: string, flag = 'file'): Promise<string> => {
  const metadata = await fs.stat(file);
  if (!metadata.isFile()) {
    throw new z.ZodError([
      {
        code: 'custom',
        path: [flag],
        message: `--${flag} must be a regular UTF-8 Markdown file`,
      },
    ]);
  }
  const bytes = await fs.readFile(file);
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    throw new z.ZodError([
      {
        code: 'custom',
        path: [flag],
        message: `--${flag} must contain valid UTF-8 text`,
      },
    ]);
  }
};

export const contextRequest = async (
  args: string[],
): Promise<ContextRequest | CliCommandResult> => {
  const command = `context.${args[0] ?? 'list'}`;
  try {
    const action = ActionSchema.parse(args[0] ?? 'list');
    const context = parseCommandContext(
      command,
      args.slice(1),
      ACTION_FLAGS[action],
    );
    if (isCommandResult(context)) return context;
    const { flags } = context;
    if (action === 'refresh') {
      const scope = sourceRefreshScope({
        family: 'context',
        positionals: flags.positionals,
        isAll: booleanFlag(flags, 'all'),
        isPreview: booleanFlag(flags, 'preview'),
      });
      return {
        command,
        projectPath: context.projectPath,
        isProjectRequest: false,
        ...('sourceId' in scope
          ? {
              method: 'POST',
              endpoint: `/guidance/${encodeURIComponent(GuidanceDocumentSchema.shape.id.parse(scope.sourceId))}/refreshes`,
              body: {},
            }
          : scope),
      };
    }
    const hasId = [
      'update',
      'show',
      'enable',
      'disable',
      'remove',
      'inspect',
      'verifier',
      'verify',
    ].includes(action);
    const ids = hasId
      ? z.tuple([GuidanceDocumentSchema.shape.id]).parse(flags.positionals)
      : z.tuple([]).parse(flags.positionals);
    const id = ids[0];
    const request: ContextRequest = {
      command,
      method: 'GET',
      endpoint: '/guidance',
      body: undefined,
      projectPath: context.projectPath,
      isProjectRequest: action === 'inspect',
    };
    if (id !== undefined) request.endpoint += `/${encodeURIComponent(id)}`;
    switch (action) {
      case 'list':
      case 'show':
        break;
      case 'verify': {
        const outputDirectory = stringFlag(flags, 'output-directory');
        request.outputDirectory = outputDirectory
          ? path.resolve(outputDirectory)
          : path.join(context.projectPath, '.rivet', 'verifier-runs');
        const inputFile = stringFlag(flags, 'input');
        if (inputFile === undefined)
          throw new z.ZodError([
            {
              code: 'custom',
              path: ['input'],
              message: 'verify requires --input with target JSON',
            },
          ]);
        request.verificationTarget = z
          .record(z.string(), z.unknown())
          .parse(JSON.parse(await readGuidanceText(path.resolve(inputFile))));
        request.endpoint += '/verifier';
        break;
      }
      case 'verifier':
        request.endpoint += '/verifier';
        break;
      case 'inspect':
        request.endpoint = `/api/variants/guidance/${encodeURIComponent(GuidanceDocumentSchema.shape.id.parse(id))}`;
        break;
      case 'remove':
        request.method = 'DELETE';
        break;
      case 'enable':
      case 'disable':
        request.method = 'PATCH';
        request.body = { isEnabled: action === 'enable' };
        break;
      case 'resolve':
        request.method = 'POST';
        request.endpoint += '/resolutions';
        request.body = guidanceSelectionFromFlags(flags);
        break;
      case 'add':
      case 'update': {
        const title = stringFlag(flags, 'title');
        const file = stringFlag(flags, 'file');
        const referenceFile = stringFlag(flags, 'references');
        const verifierFile = stringFlag(flags, 'verifier');
        const packageFile = stringFlag(flags, 'verifier-package');
        const sourceDigest = stringFlag(flags, 'source-digest');
        const isRemovingVerifier = booleanFlag(flags, 'remove-verifier');
        const sourceRequest = await contextSourceRequest({
          action,
          sourceFile: stringFlag(flags, 'source'),
          isRemovingSource: booleanFlag(flags, 'remove-source'),
          title,
          hasContent:
            [file, referenceFile, verifierFile, packageFile, sourceDigest].some(
              (value) => value !== undefined,
            ) || isRemovingVerifier,
        });
        if (sourceRequest) {
          request.method = sourceRequest.method;
          request.endpoint += sourceRequest.suffix;
          request.body = sourceRequest.body;
          return request;
        }
        if (
          (isRemovingVerifier &&
            (verifierFile !== undefined ||
              packageFile !== undefined ||
              sourceDigest !== undefined)) ||
          (verifierFile === undefined &&
            (sourceDigest !== undefined || packageFile !== undefined))
        )
          throw new z.ZodError([
            {
              code: 'custom',
              path: ['verifier'],
              message:
                'Use --verifier with --source-digest, or --remove-verifier alone',
            },
          ]);
        const verifier =
          verifierFile === undefined
            ? undefined
            : {
                markdown: await readMarkdown(
                  path.resolve(verifierFile),
                  'verifier',
                ),
                sourceDigest,
                ...(packageFile !== undefined
                  ? {
                      package: await guidanceVerifierPackage(
                        path.resolve(packageFile),
                      ),
                    }
                  : {}),
              };

        const references =
          referenceFile === undefined
            ? undefined
            : await guidanceReferences(path.resolve(referenceFile));
        const input = {
          ...(verifier !== undefined ? { verifier } : {}),
          ...(isRemovingVerifier ? { verifier: null } : {}),
          ...(title !== undefined ? { title } : {}),
          ...(references !== undefined ? { references } : {}),
          ...(action === 'add' && file === undefined && references?.length
            ? { markdown: 'Apply the saved references below where relevant.' }
            : {}),
          ...(file !== undefined
            ? await guidanceUpload(
                path.resolve(file),
                await readMarkdown(path.resolve(file)),
              )
            : {}),
        };
        request.method = action === 'add' ? 'POST' : 'PATCH';
        request.body =
          action === 'add'
            ? GuidanceUploadSchema.parse(input)
            : GuidanceUploadUpdateSchema.parse(input);
        break;
      }
    }
    return request;
  } catch (error) {
    return errorResult(
      command,
      error instanceof z.ZodError ? 'USAGE_ERROR' : 'OPERATION_FAILED',
      errorMessage(error, 'Could not read saved context input'),
    );
  }
};
